<body>
  <!-- Hero Section -->
  <section class="hero">
    <canvas id="coin-hero" width="512" height="512"></canvas>
    <h1>WastedToken Mint</h1>
    <p>Crafting premium collectible challenge coins for the discerning collector. Each coin is meticulously minted with exceptional detail and a luxurious metallic finish.</p>
  </section>

  <!-- About Section -->
  <section class="about">
    <h2>About WastedToken Mint</h2>
    <p>WastedToken Mint was founded in 2024 with a singular mission: to create the finest collectible challenge coins that celebrate community, achievement, and digital culture.</p>
    <p>Every coin in our collection is crafted from high-quality materials and features intricate designs that honor the spirit of innovation and the legacy of digital collectibles.</p>
    <ul>
      <li><strong>Premium Materials:</strong> Bronze, Silver, Gold, and Obsidian finishes</li>
      <li><strong>Limited Editions:</strong> Each collection is capped to ensure exclusivity</li>
      <li><strong>Authenticity Guaranteed:</strong> Every coin comes with a certificate of authenticity</li>
      <li><strong>Community Focused:</strong> Designed by collectors, for collectors</li>
    </ul>
  </section>

  <!-- Collection Grid -->
  <section class="collection">
    <h2>Exclusive Collections</h2>
    <div class="grid">
      <!-- Bronze Edition -->
      <div class="edition" data-edition="bronze" data-state="available">
        <canvas class="edition-canvas" width="150" height="150"></canvas>
        <h3>Bronze Edition</h3>
        <div class="state">Available</div>
        <button class="buy">Add to cart</button>
      </div>

      <!-- Silver Edition -->
      <div class="edition" data-edition="silver" data-state="available">
        <canvas class="edition-canvas" width="150" height="150"></canvas>
        <h3>Silver Edition</h3>
        <div class="state">Available</div>
        <button class="buy">Add to cart</button>
      </div>

      <!-- Gold Edition -->
      <div class="edition" data-edition="gold" data-state="sold-out">
        <canvas class="edition-canvas" width="150" height="150"></canvas>
        <h3>Gold Edition</h3>
        <div class="state">SOLD OUT</div>
        <button class="buy" disabled>SOLD OUT</button>
      </div>

      <!-- Black (Obsidian) Edition -->
      <div class="edition" data-edition="black" data-state="coming-soon">
        <canvas class="edition-canvas" width="150" height="150"></canvas>
        <h3>Obsidian Edition</h3>
        <div class="state">MINTING NEXT SEASON - SPRING</div>
        <button class="buy" disabled>Coming Soon</button>
      </div>
    </div>
  </section>

  <!-- Footer -->
  <footer>
    <p>&copy; 2024 WastedToken Mint. All rights reserved. | Collectible Challenge Coins</p>
  </footer>

<script>
// ==================== HERO COIN ====================
const heroCanvas = document.getElementById('coin-hero');
const heroCtx = heroCanvas.getContext('2d');

// Coin properties
const COIN_RADIUS = 200;
const RIM_WIDTH = 25;
const REEDED_SEGMENTS = 180;

// Animation state
let heroTime = 0;
let heroAnimationId = null;
let heroIsPlaying = true;

function heroDraw() {
  const t = heroTime % 1;

  // Clear canvas
  heroCtx.fillStyle = '#0a0a0f';
  heroCtx.fillRect(0, 0, heroCanvas.width, heroCanvas.height);

  // Coin center
  const cx = heroCanvas.width / 2;
  const cy = heroCanvas.height / 2;

  // Rotation angles
  const rotateY = t * Math.PI * 2; // Full Y-axis rotation
  const flipX = Math.sin(t * Math.PI * 2) * 0.3; // X-axis flip (oscillation)

  // Draw coin
  drawCoin(heroCtx, cx, cy, COIN_RADIUS, RIM_WIDTH, rotateY, flipX, t);

  if (heroIsPlaying) {
    heroAnimationId = requestAnimationFrame(heroDraw);
    heroTime += 0.008;
  }
}

function drawCoin(ctx, cx, cy, radius, rimWidth, rotY, flipX, t) {
  ctx.save();
  ctx.translate(cx, cy);

  // Apply rotations
  ctx.rotate(flipX);
  ctx.rotate(rotY);

  // Determine visible face
  const cosY = Math.cos(rotY);
  const sinY = Math.sin(rotY);
  const cosX = Math.cos(flipX);

  // Determine which face to show
  let showFront = cosY >= 0;
  let faceOffset = 0;

  // Add some logic to show both faces
  if (cosY > -0.2 && cosY < 0.2) {
    // Side view - show rim
    showFront = rotY < Math.PI;
  }

  // Draw reeded edge
  drawReededEdge(ctx, radius, rimWidth, t, rotY, flipX);

  // Draw faces
  if (Math.abs(cosY) > 0.2) {
    drawFace(ctx, radius, rimWidth, showFront, t, rotY);
  }

  ctx.restore();
}

function drawReededEdge(ctx, radius, rimWidth, t, rotY, flipX) {
  const outerRadius = radius;
  const innerRadius = radius - rimWidth;

  // Metallic gradient for edge
  const gradient = ctx.createRadialGradient(0, 0, innerRadius, 0, 0, outerRadius);
  gradient.addColorStop(0, '#C0C0C0');
  gradient.addColorStop(0.5, '#A9A9A9');
  gradient.addColorStop(1, '#808080');

  ctx.fillStyle = gradient;

  // Draw reeded segments
  ctx.beginPath();
  for (let i = 0; i < REEDED_SEGMENTS; i++) {
    const angle = (i / REEDED_SEGMENTS) * Math.PI * 2;
    const nextAngle = ((i + 1) / REEDED_SEGMENTS) * Math.PI * 2;

    const x1 = innerRadius * Math.cos(angle);
    const y1 = innerRadius * Math.sin(angle);
    const x2 = outerRadius * Math.cos(angle);
    const y2 = outerRadius * Math.sin(angle);

    const x3 = outerRadius * Math.cos(nextAngle);
    const y3 = outerRadius * Math.sin(nextAngle);
    const x4 = innerRadius * Math.cos(nextAngle);
    const y4 = innerRadius * Math.sin(nextAngle);

    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineTo(x3, y3);
    ctx.lineTo(x4, y4);
    ctx.closePath();
  }
  ctx.fill();
}

function drawFace(ctx, radius, rimWidth, isFront, t, rotY) {
  const faceRadius = radius - rimWidth - 5;

  // Metallic gradient with specular highlight
  const lightDirX = Math.sin(t * Math.PI * 2) * 0.5 + 0.5;
  const lightDirY = Math.cos(t * Math.PI * 2) * 0.3 + 0.7;

  // Base metal color
  let baseColor, highlightColor, shadowColor;

  if (isFront) {
    // Gold-ish front face
    baseColor = '#D4AF37';
    highlightColor = '#FFD700';
    shadowColor = '#B8860B';
  } else {
    // Silver-ish back face
    baseColor = '#C0C0C0';
    highlightColor = '#E8E8E8';
    shadowColor = '#A9A9A9';
  }

  const gradient = ctx.createRadialGradient(
    faceRadius * lightDirX * 0.3,
    faceRadius * lightDirY * 0.3,
    faceRadius * 0.1,
    0, 0,
    faceRadius
  );

  gradient.addColorStop(0, highlightColor);
  gradient.addColorStop(0.5, baseColor);
  gradient.addColorStop(1, shadowColor);

  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(0, 0, faceRadius, 0, Math.PI * 2);
  ctx.fill();

  // Draw emblem (front) or denomination (back)
  ctx.save();
  ctx.fillStyle = isFront ? '#000' : '#222';

  if (isFront) {
    // Embossed WTM emblem
    drawEmblem(ctx, faceRadius, t);
  } else {
    // Denomination text
    drawDenomination(ctx, faceRadius);
  }

  ctx.restore();

  // Specular highlight that moves across surface
  const specGrad = ctx.createRadialGradient(
    faceRadius * lightDirX,
    faceRadius * lightDirY,
    faceRadius * 0.05,
    faceRadius * lightDirX,
    faceRadius * lightDirY,
    faceRadius * 0.8
  );
  specGrad.addColorStop(0, 'rgba(255, 255, 255, 0.6)');
  specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.2)');
  specGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');

  ctx.fillStyle = specGrad;
  ctx.beginPath();
  ctx.arc(0, 0, faceRadius, 0, Math.PI * 2);
  ctx.fill();

  // Rim highlight/shadow
  const rimGrad = ctx.createRadialGradient(0, 0, faceRadius - rimWidth, 0, 0, faceRadius);
  rimGrad.addColorStop(0, 'rgba(255, 255, 255, 0)');
  rimGrad.addColorStop(0.8, 'rgba(255, 255, 255, 0.3)');
  rimGrad.addColorStop(1, 'rgba(0, 0, 0, 0.3)');

  ctx.fillStyle = rimGrad;
  ctx.beginPath();
  ctx.arc(0, 0, faceRadius, 0, Math.PI * 2);
  ctx.fill();
}

function drawEmblem(ctx, radius, t) {
  const scale = radius / 200;

  // Outer ring
  ctx.save();
  ctx.scale(scale, scale);
  ctx.lineWidth = 8;
  ctx.strokeStyle = '#000';
  ctx.beginPath();
  ctx.arc(0, 0, 80, 0, Math.PI * 2);
  ctx.stroke();

  // Inner design - stylized "WTM"
  ctx.font = 'bold 40px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#000';
  ctx.fillText('WTM', 0, 0);

  // Decorative lines
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 3;
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x1 = 90 * Math.cos(angle);
    const y1 = 90 * Math.sin(angle);
    const x2 = 100 * Math.cos(angle);
    const y2 = 100 * Math.sin(angle);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  ctx.restore();
}

function drawDenomination(ctx, radius) {
  const scale = radius / 200;

  ctx.save();
  ctx.scale(scale, scale);

  // Token count text
  ctx.font = 'bold 32px Arial';
  ctx.textAlign = 'center';
  ctx.fillStyle = '#000';
  ctx.fillText('10,000', 0, -15);

  ctx.font = 'bold 24px Arial';
  ctx.fillText('TOKENS', 0, 15);

  // Border circle
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(0, 0, 100, 0, Math.PI * 2);
  ctx.stroke();

  ctx.restore();
}

// Start hero animation
heroIsPlaying = true;
heroDraw();

// ==================== EDITION COINS ====================
const editionCanvases = document.querySelectorAll('.edition-canvas');
const editions = ['bronze', 'silver', 'gold', 'black'];

function initEditionCoins() {
  editionCanvases.forEach((canvas, index) => {
    const ctx = canvas.getContext('2d');
    const edition = editions[index];
    drawEditionCoin(ctx, canvas.width / 2, canvas.height / 2, 70, edition);
  });
}

function drawEditionCoin(ctx, cx, cy, radius, edition) {
  const rimWidth = 10;
  const faceRadius = radius - rimWidth;

  // Set base colors based on edition
  let baseColor, highlightColor, shadowColor;

  switch(edition) {
    case 'bronze':
      baseColor = '#CD7F32';
      highlightColor = '#DAA520';
      shadowColor = '#8B4513';
      break;
    case 'silver':
      baseColor = '#C0C0C0';
      highlightColor = '#E8E8E8';
      shadowColor = '#A9A9A9';
      break;
    case 'gold':
      baseColor = '#FFD700';
      highlightColor = '#FFEA00';
      shadowColor = '#B8860B';
      break;
    case 'black':
      baseColor = '#2F2F2F';
      highlightColor = '#5A5A5A';
      shadowColor = '#1A1A1A';
      break;
  }

  // Draw reeded edge
  const gradient = ctx.createRadialGradient(cx, cy, faceRadius, cx, cy, radius);
  gradient.addColorStop(0, '#888');
  gradient.addColorStop(0.5, '#666');
  gradient.addColorStop(1, '#444');

  ctx.fillStyle = gradient;
  ctx.beginPath();
  for (let i = 0; i < 30; i++) {
    const angle = (i / 30) * Math.PI * 2;
    const nextAngle = ((i + 1) / 30) * Math.PI * 2;

    const x1 = cx + faceRadius * Math.cos(angle);
    const y1 = cy + faceRadius * Math.sin(angle);
    const x2 = cx + radius * Math.cos(angle);
    const y2 = cy + radius * Math.sin(angle);

    const x3 = cx + radius * Math.cos(nextAngle);
    const y3 = cy + radius * Math.sin(nextAngle);
    const x4 = cx + faceRadius * Math.cos(nextAngle);
    const y4 = cy + faceRadius * Math.sin(nextAngle);

    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineTo(x3, y3);
    ctx.lineTo(x4, y4);
    ctx.closePath();
  }
  ctx.fill();

  // Draw face
  const faceGrad = ctx.createRadialGradient(
    cx + faceRadius * 0.3,
    cy - faceRadius * 0.3,
    faceRadius * 0.1,
    cx, cy,
    faceRadius
  );
  faceGrad.addColorStop(0, highlightColor);
  faceGrad.addColorStop(0.5, baseColor);
  faceGrad.addColorStop(1, shadowColor);

  ctx.fillStyle = faceGrad;
  ctx.beginPath();
  ctx.arc(cx, cy, faceRadius, 0, Math.PI * 2);
  ctx.fill();

  // Draw emblem
  ctx.save();
  ctx.fillStyle = '#000';
  ctx.font = `bold ${Math.round(faceRadius * 0.5)}px Arial`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(edition === 'black' ? 'OB' : edition.charAt(0).toUpperCase() + edition.slice(1, 3), cx, cy);
  ctx.restore();

  // Specular highlight
  const specGrad = ctx.createRadialGradient(
    cx + faceRadius * 0.3,
    cy - faceRadius * 0.3,
    faceRadius * 0.05,
    cx, cy,
    faceRadius
  );
  specGrad.addColorStop(0, 'rgba(255, 255, 255, 0.5)');
  specGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');

  ctx.fillStyle = specGrad;
  ctx.beginPath();
  ctx.arc(cx, cy, faceRadius, 0, Math.PI * 2);
  ctx.fill();
}

// Initialize edition coins
initEditionCoins();

// ==================== WEB DEMO API ====================
window.demo = {
  canvas: heroCanvas,
  setTime(t) {
    // Render EXACTLY that point of the loop, synchronously
    heroIsPlaying = false;
    if (heroAnimationId) {
      cancelAnimationFrame(heroAnimationId);
    }
    const oldTime = heroTime;
    heroTime = t;
    heroCtx.fillStyle = '#0a0a0f';
    heroCtx.fillRect(0, 0, heroCanvas.width, heroCanvas.height);

    const cx = heroCanvas.width / 2;
    const cy = heroCanvas.height / 2;
    const rotateY = t * Math.PI * 2;
    const flipX = Math.sin(t * Math.PI * 2) * 0.3;

    drawCoin(heroCtx, cx, cy, COIN_RADIUS, RIM_WIDTH, rotateY, flipX, t);
  },
  pause() {
    heroIsPlaying = false;
    if (heroAnimationId) {
      cancelAnimationFrame(heroAnimationId);
    }
  }
};
</script>
</body>
</html>
